<script setup lang="ts">
import DismissibleNotice from './DismissibleNotice.vue';
import {ref,onMounted} from 'vue';
import {developerDiagnostics as d,lockDiagnostics,createDeveloperLock,verifyDeveloperLock,validDeveloperLock,developerLockKey,type DeveloperLock} from '../app/developerDiagnostics';
const configured=ref<DeveloperLock>(),password=ref(''),confirmation=ref(''),problem=ref(''),busy=ref(false),loaded=ref(false);
onMounted(()=>{try{const value=JSON.parse(localStorage.getItem(developerLockKey)||'null');if(validDeveloperLock(value))configured.value=value;}catch{problem.value='本机开发密令读取失败';}finally{loaded.value=true;}});
async function unlock(){busy.value=true;problem.value='';try{if(!configured.value){if(password.value!==confirmation.value)throw Error('两次密令不一致');const value=await createDeveloperLock(password.value);localStorage.setItem(developerLockKey,JSON.stringify(value));configured.value=value;}else if(!await verifyDeveloperLock(password.value,configured.value))throw Error('密令不正确');d.unlocked=true;password.value='';confirmation.value='';}catch(e){problem.value=e instanceof Error?e.message:'开发诊断未解锁';}finally{busy.value=false;}}
</script>
<template><section class="developer-diagnostics"><h3>本机开发者模式（诊断）</h3><p>查看状态解析位置、格式兼容处理、输出长度和补修次数；不包含思维链、原始提示词或 Key。</p><form v-if="loaded&&!d.unlocked" @submit.prevent="unlock"><label>{{configured?'开发密令':'首次设置开发密令'}}<input v-model="password" type="password" autocomplete="off" maxlength="200" :disabled="busy" required /></label><label v-if="!configured">再次输入<input v-model="confirmation" type="password" autocomplete="off" maxlength="200" :disabled="busy" required /></label><button type="submit" :disabled="busy||!password">{{busy?'处理中…':configured?'解锁诊断':'设置并解锁'}}</button></form><DismissibleNotice :message="problem" error /><template v-if="d.unlocked"><div class="actions"><button @click="lockDiagnostics">锁定</button><button @click="d.entries=[]">清空诊断</button></div><p v-if="!d.entries.length">已解锁。下一次生成或补修状态后显示诊断。</p><article v-for="(entry,i) in d.entries" :key="i"><strong>{{entry.at}} · {{entry.stage==='accepted'?'已通过':'未通过'}} · {{entry.attempt===0?'首次请求':'补修／续写 '+entry.attempt}}</strong><p v-if="entry.format==='normalized'">已兼容处理 {{entry.controls||0}} 个字符串控制符、{{entry.trailingCommas||0}} 个尾随逗号。</p><p v-if="entry.category">{{entry.category==='incomplete'?'JSON 字符串或容器尚未闭合':entry.category==='not-object'?'状态块含额外文字或不是 JSON':'JSON 语法错误'}}<span v-if="entry.line!==undefined"> · 规范化后的第 {{entry.line}} 行，第 {{entry.column}} 列</span></p><pre>{{JSON.stringify(entry,null,2)}}</pre></article></template></section></template>
<style scoped>.developer-diagnostics{margin-top:1rem;border-top:1px solid var(--color-border);padding-top:1rem}.developer-diagnostics pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:20rem;overflow:auto}.developer-diagnostics article{margin-top:1rem}</style>
